def solve(inputs: dict) -> float:
    import re
    # Try to extract from structured inputs first
    x = None
    a = None
    m = None
    steps = None
    # common key names
    for k, v in inputs.items():
        kl = str(k).lower()
        if 'start' in kl or kl in ('x', 'x0', 'seed'):
            x = int(v)
        elif 'add' in kl or 'const' in kl or kl == 'c':
            a = int(v)
        elif 'mod' in kl:
            m = int(v)
        elif 'step' in kl or 'iter' in kl or kl == 'n':
            steps = int(v)
    if None in (x, a, m, steps):
        # parse from a text field
        text = ' '.join(str(v) for v in inputs.values())
        nums = list(map(int, re.findall(r'-?\d+', text)))
        # pattern: a (add const), m (mod), steps, x (start)
        # from problem text order: add const, mod, steps, start
        if len(nums) >= 4:
            a, m, steps, x = nums[0], nums[1], nums[2], nums[3]
    for _ in range(steps):
        x = (x * x + a) % m
    return float(x)

