def solve(inputs: dict) -> float:
    import re
    rems = None
    mods = None
    for k, v in inputs.items():
        kl = str(k).lower()
        if 'rem' in kl:
            if isinstance(v, (list, tuple)):
                rems = [int(x) for x in v]
            else:
                rems = list(map(int, re.findall(r'-?\d+', str(v))))
        elif 'mod' in kl:
            if isinstance(v, (list, tuple)):
                mods = [int(x) for x in v]
            else:
                mods = list(map(int, re.findall(r'-?\d+', str(v))))
    if rems is None or mods is None:
        text = ' '.join(str(v) for v in inputs.values())
        # find bracketed lists
        lists = re.findall(r'\[([^\]]*)\]', text)
        parsed = [list(map(int, re.findall(r'-?\d+', l))) for l in lists]
        if len(parsed) >= 2:
            rems, mods = parsed[0], parsed[1]
    # CRT
    x = 0
    M = 1
    for m in mods:
        M *= m
    for r, m in zip(rems, mods):
        Mi = M // m
        # inverse of Mi mod m
        inv = pow(Mi, -1, m)
        x = (x + r * Mi * inv) % M
    return float(x % M)

