def solve(inputs: dict) -> float:
    import re
    n = None
    k = None
    for key, v in inputs.items():
        kl = str(key).lower()
        if 'people' in kl or 'n' == kl or 'count' in kl or 'circle' in kl:
            try:
                n = int(v)
            except:
                pass
        if 'step' in kl or 'k' == kl or 'every' in kl or 'nth' in kl:
            try:
                k = int(v)
            except:
                pass
    if n is None or k is None:
        text = ' '.join(str(v) for v in inputs.values())
        nums = list(map(int, re.findall(r'-?\d+', text)))
        # first big number is people count; the "every k-th" is k
        # heuristic: n is the largest, k is small
        if nums:
            n = max(nums)
            # k is the number just before 'th' ; find smallest plausible
            others = [x for x in nums if x != n]
            k = min(others) if others else 1
    # Josephus, 1-indexed
    res = 0
    for i in range(2, n + 1):
        res = (res + k) % i
    return float(res + 1)

